<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {RouterLink} from 'vue-router'
import api from '@/api/client'
const current=ref(''),next=ref(''),confirm=ref(''),message=ref(''),busy=ref(false)
const policyLoading=ref(true)
const prefixes=ref(''),smsLimit=ref(20),policyMessage=ref('')
onMounted(async()=>{try{const p=(await api.get('/business/policy')).data;prefixes.value=(Array.isArray(p.allowed_prefixes)?p.allowed_prefixes:[]).join(', ');smsLimit.value=p.sms_per_minute}catch{policyMessage.value='Could not load usage controls'}finally{policyLoading.value=false}})
async function policy(){busy.value=true;try{await api.put('/business/policy',{allowed_prefixes:prefixes.value.split(',').map(p=>p.trim()).filter(Boolean),sms_per_minute:smsLimit.value});policyMessage.value='Usage controls saved'}catch{policyMessage.value='Use prefixes such as +44, +91 and an SMS limit from 1 to 120'}finally{busy.value=false}}
const automation=ref({demo_mode:false,ai_enabled:false,key_set:false,missed_call_url_set:false,sms_url_set:false}),automationMessage=ref(''),automationLoading=ref(true)
onMounted(async()=>{try{automation.value=(await api.get('/business/automation')).data}catch{automationMessage.value='Could not load automation settings'}finally{automationLoading.value=false}})
async function saveAutomation(field:'demo_mode'|'ai_enabled',value:boolean){automationMessage.value='';try{automation.value=(await api.put('/business/automation',{[field]:value})).data;automationMessage.value='Saved'}catch{automationMessage.value='Could not save. Try again.'}}
async function change(){message.value='';if(next.value!==confirm.value){message.value='Passwords do not match';return}busy.value=true;try{await api.put('/me/password',{current_password:current.value,new_password:next.value});message.value='Administrator password changed';current.value='';next.value='';confirm.value=''}catch(e){message.value=(e as {response?:{data?:{error?:{message?:string}}}}).response?.data?.error?.message||'Password could not be changed'}finally{busy.value=false}}
</script>
<template><div class="space-y-6 settings-page"><h1 class="text-2xl font-semibold">Settings</h1><form @submit.prevent="change" class="settings-card space-y-4"><h2 class="font-semibold">Change your administrator password</h2><label class="block">Current password<input v-model="current" type="password" autocomplete="current-password" required class="block w-full border rounded p-2 mt-1 dark:bg-gray-700"/></label><label class="block">New password<input v-model="next" type="password" autocomplete="new-password" minlength="12" maxlength="72" required class="block w-full border rounded p-2 mt-1 dark:bg-gray-700"/></label><label class="block">Confirm password<input v-model="confirm" type="password" autocomplete="new-password" required class="block w-full border rounded p-2 mt-1 dark:bg-gray-700"/></label><p>{{message}}</p><button :disabled="busy" class="bg-primary text-white rounded px-4 py-2">Change password</button></form><form @submit.prevent="policy" class="settings-card space-y-4"><h2 class="font-semibold">Usage controls</h2><label class="block">Allowed international prefixes<input v-model="prefixes" :disabled="policyLoading" placeholder="+44, +91" class="block w-full border rounded p-2 mt-1 dark:bg-gray-700"/></label><p class="text-sm text-gray-500">Comma-separated prefixes for outgoing calls and SMS. An empty field allows all destinations. Choose only the countries your team needs.</p><label class="block">SMS per minute per number<input v-model.number="smsLimit" :disabled="policyLoading" type="number" min="1" max="120" required class="block w-full border rounded p-2 mt-1 dark:bg-gray-700"/></label><p class="text-sm text-gray-500">Up to two concurrent outgoing calls per SIP user.</p><p>{{policyMessage}}</p><button :disabled="busy||policyLoading" class="bg-primary text-white rounded px-4 py-2">Save usage controls</button></form><div class="settings-card space-y-4"><h2 class="font-semibold">Missed-call text-back &amp; AI replies (n8n)</h2><p v-if="!automationLoading&&!(automation.key_set&&automation.missed_call_url_set&&automation.sms_url_set)" class="text-sm text-amber-500">Not fully connected: set GOSIP_AUTOMATION_KEY, GOSIP_N8N_MISSED_CALL_URL and GOSIP_N8N_SMS_URL in Coolify and redeploy.</p><label class="flex items-start gap-3"><input type="checkbox" class="mt-1" :checked="automation.demo_mode" :disabled="automationLoading||!automation.key_set||!automation.missed_call_url_set" @change="saveAutomation('demo_mode',($event.target as HTMLInputElement).checked)"/><span><span class="font-medium">Demo mode</span><span class="block text-sm text-gray-500">On: calls don't ring the phone; they're rejected as busy and the caller gets the text-back straight away. Off: the phone rings for 30 seconds and the text-back is sent only if you don't answer.</span></span></label><label class="flex items-start gap-3"><input type="checkbox" class="mt-1" :checked="automation.ai_enabled" :disabled="automationLoading||!automation.key_set||!automation.sms_url_set" @change="saveAutomation('ai_enabled',($event.target as HTMLInputElement).checked)"/><span><span class="font-medium">AI replies to SMS</span><span class="block text-sm text-gray-500">The n8n assistant answers texts only from people who called (and got the missed-call text-back), for 24 hours after their last message. Replies to your outreach texts from people who haven't called go to you only. When you reply yourself, the AI pauses for that contact for 24 hours. Anyone who texts STOP is never messaged by automation again (START undoes it).</span></span></label><p class="text-sm" role="status">{{automationMessage}}</p></div><div class="settings-card space-y-3"><h2 class="font-semibold">Server configuration</h2><p>Twilio Account SID and Auth Token are managed in Coolify environment variables. The server must keep its SIP certificate renewal/export configured; phones use SRTP.</p><p>The phone user and phone password are set in the Coolify environment. Choose the phone's Twilio number under Phone Numbers. Incoming calls ring the phone for 30 seconds, then go to voicemail.</p><RouterLink to="/" class="block text-primary">Service health, backups and change history →</RouterLink><RouterLink to="/users" class="block text-primary">Manage web console administrators →</RouterLink></div></div></template>
